// Normalize actor output, remove duplicate companies, and cap the run.
const settings = $('Your settings (EDIT ME)').first().json;
const maxExhibitors = Math.min(25, Math.max(1, Number(settings.maxExhibitorsPerRun) || 25));
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  if (j.error) continue;
  const companyName = String(j.companyName ?? j.company ?? j.exhibitorName ?? j.name ?? j.title ?? '').trim();
  if (!companyName) continue;
  const key = companyName.toLowerCase().replace(/\s+/g, ' ');
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: {
    companyName,
    contactName: String(j.contactName ?? j.contact ?? j.representativeName ?? j.ownerName ?? ''),
    contactEmail: String(j.contactEmail ?? j.email ?? ''),
    website: String(j.website ?? j.websiteUrl ?? j.companyUrl ?? ''),
    boothOrListingDetail: String(j.boothOrListingDetail ?? j.booth ?? j.boothNumber ?? j.location ?? j.description ?? j.category ?? ''),
    sourceUrl: String(j.sourceUrl ?? j.url ?? j.profileUrl ?? settings.exhibitorDirectoryUrl ?? ''),
    tradeShowUrl: settings.tradeShowUrl,
    exhibitorDirectoryUrl: settings.exhibitorDirectoryUrl,
    icpDescription: settings.icpDescription
  } });
  if (out.length >= maxExhibitors) break;
}
if (out.length === 0) return [{ json: { _empty: true, note: 'No exhibitors survived normalization this run.' } }];
return out;

