// Parse the AI response and create the final Google Sheets row.
const rows = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  let verdict = { score: 0, reason: 'AI call failed - inspect the execution log' };
  try {
    const content = j.choices?.[0]?.message?.content;
    if (content) verdict = JSON.parse(content);
  } catch (error) {
    verdict = { score: 0, reason: 'AI returned unparseable output - inspect the execution log' };
  }
  rows.push({ json: {
    processedAt: new Date().toISOString(),
    companyName: String(j.companyName ?? ''),
    contactName: String(j.contactName ?? ''),
    contactEmail: String(j.contactEmail ?? ''),
    website: String(j.website ?? ''),
    boothOrListingDetail: String(j.boothOrListingDetail ?? ''),
    sourceUrl: String(j.sourceUrl ?? ''),
    tradeShowUrl: String(j.tradeShowUrl ?? ''),
    exhibitorDirectoryUrl: String(j.exhibitorDirectoryUrl ?? ''),
    icpScore: Math.min(10, Math.max(0, Number(verdict.score) || 0)),
    reason: String(verdict.reason ?? '')
  } });
}
return rows;
